begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('73000000-0000-4000-8000-000000000001','playlist-authoring@example.test',now());
create temporary table playlist_authoring_state(name text primary key,value jsonb);
grant select,insert,update on playlist_authoring_state to authenticated;
insert into playlist_authoring_state values('scenarioContent','{"title": "Utility before the next fight", "topic": "Utility timing", "context": "Bind, attacking at 7–3. You are Clove near A Short/Lamps with a Vandal reload in progress. Your teammates are taking A while smokes obscure parts of the site. Decide what to do as the reload completes.", "question": "You are finishing your reload while your team takes A. What do you do next?", "knownFacts": ["At the pause, both teams still have five players alive.", "You have 100 HP and 50 armour; your Vandal reload is in progress.", "Nearby teammates and A-site smokes are visible from your POV."], "unknowns": ["Exact enemy positions behind the smoke and cover.", "Whether a teammate has explicitly taken over your angle.", "Complete team communications and the intended utility target."], "takeaway": "Choose a utility window around who can cover the next contact and who can exploit the timing.", "outcomeText": "Meddle is visibly equipped and released, followed by rifle fire. This sequence does not confirm an enemy hit or establish that the utility caused a later kill.", "source": {"url": "https://www.youtube.com/watch?v=_yPrykaB2nE", "title": "WASHED GAMER PLAYS APAC RANKED", "uploader": "TenZ", "player": "TenZ", "map": "Bind", "agent": "Clove", "score": "7-3", "matchType": "ranked", "round": 11, "side": "attack", "publishedDate": "2025-08-15", "dateNote": "YouTube displayed August 15, 2025; earlier indexed metadata used August 14. The reason for this date discrepancy is unverified."}, "media": {"startSeconds": 1705, "decisionSeconds": 1713, "endSeconds": 1718, "setupAlt": "TenZ''s Clove POV approaching the smoked A site on Bind and beginning a Vandal reload.", "decisionAlt": "Paused before the next action: a reload is finishing near A Short/Lamps while teammates take the site.", "revealAlt": "TenZ completes the reload, throws Clove''s Meddle toward A-site cover, and returns to the rifle."}, "options": [{"id": "11111111-1111-4111-8111-111111111111", "label": "Throw Meddle toward site cover, then ready the rifle", "assessment": "reasonable", "explanation": "A short protected utility window can prepare the next fight while your teammates gain space. Its value depends on their ability to cover the animation and act on the timing; the smoke prevents certainty about the target.", "acceptableWhen": ["A teammate can cover the immediate contact while your weapon is unavailable.", "The team is close enough to exploit the utility timing."], "risks": ["An immediate fight may arrive during the equip and throw animation.", "Hidden enemy positions can make the throw ineffective."]}, {"id": "22222222-2222-4222-8222-222222222222", "label": "Keep the rifle ready and cover the next contact", "assessment": "reasonable", "explanation": "Keeping your rifle ready preserves an immediate trade if a teammate meets resistance. That can be preferable when responsibility for the angle is unclear, although it delays the utility window.", "acceptableWhen": ["A teammate may need an immediate trade from your current angle.", "No one has clearly taken over your weapon coverage."], "risks": ["Waiting can miss the opportunity to combine utility with the site''s entry timing.", "Your angle may duplicate a teammate''s coverage instead of adding support."]}, {"id": "33333333-3333-4333-8333-333333333333", "label": "Advance with a teammate and retain Meddle", "assessment": "reasonable", "explanation": "Moving closer can improve access to the next trade while retaining utility for new information. It is conditional on the route being clear and the movement creating useful spacing rather than another exposed player.", "acceptableWhen": ["The path is clear enough to move with your weapon ready.", "The new position gives you a timely trade without abandoning necessary coverage."], "risks": ["Smokes and cover can conceal angles along the route.", "Advancing without coordination can duplicate exposure and lose the original angle."]}], "observedAction": {"optionId": "11111111-1111-4111-8111-111111111111", "description": "TenZ finishes the reload, equips Meddle, throws it toward A-site cover, then re-equips the Vandal and fires from the position."}, "analysis": {"author": "creator", "rationale": "This choice uses a brief moment near cover to prepare the next engagement. The relevant tradeoff is utility timing versus immediate weapon coverage. The POV supports what was thrown, but does not establish a uniquely best choice without the team''s coverage and timing commitments.", "limitations": ["The selected footage does not establish that Meddle affected an enemy or caused a kill.", "Complete communications and the player''s intended target are unknown.", "Several options can be defensible under different coverage assumptions."]}}'::jsonb),('scenarioChecklist','{"povInformationChecked": true, "setupSpoilersChecked": true, "pauseTimingChecked": true, "continuationChecked": true, "normalSpeedAudioChecked": true, "alternativeChoicesChecked": true, "sourceAttributionChecked": true}'::jsonb),('playlistChecklist','{"orderChecked": true, "selectedVersionsChecked": true, "mixedPlayersChecked": true, "creditChecked": true}'::jsonb);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"73000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.enable_creator();
select public.save_creator_profile('73000000-0000-4000-8000-000000000010',0,'Coach');
insert into playlist_authoring_state values('scenario',public.create_creator_scenario('73000000-0000-4000-8000-000000000011')->'scenario');
update playlist_authoring_state set value=public.save_creator_scenario(value->>'id','73000000-0000-4000-8000-000000000012',0,(select value from playlist_authoring_state where name='scenarioContent'))->'scenario' where name='scenario';
update playlist_authoring_state set value=public.review_creator_scenario(value->>'id','73000000-0000-4000-8000-000000000013',1,(select value from playlist_authoring_state where name='scenarioChecklist'))->'scenario' where name='scenario';
update playlist_authoring_state set value=public.publish_creator_scenario(value->>'id','73000000-0000-4000-8000-000000000014',2,(value->'review'->>'id')::uuid)->'scenario' where name='scenario';
insert into playlist_authoring_state values('playlist',public.create_creator_playlist('73000000-0000-4000-8000-000000000015')->'playlist');
insert into playlist_authoring_state select 'playlistContent',jsonb_build_object('title','Practice one','description','A saved plan.','items',jsonb_build_array(jsonb_build_object('scenarioId',value->>'id','scenarioVersion','creator-1'))) from playlist_authoring_state where name='scenario';
update playlist_authoring_state set value=public.save_creator_playlist((value->>'id')::uuid,'73000000-0000-4000-8000-000000000016',0,(select value from playlist_authoring_state where name='playlistContent'))->'playlist' where name='playlist';
select is(value->'readiness'->>'canReview','true','own published selected version is reviewable') from playlist_authoring_state where name='playlist';
select is(public.get_creator_playlist_review_preview((value->>'id')::uuid,1)->>'profileRevision','1','preview binds public credit revision') from playlist_authoring_state where name='playlist';
update playlist_authoring_state set value=public.review_creator_playlist((value->>'id')::uuid,'73000000-0000-4000-8000-000000000017',1,1,(select value from playlist_authoring_state where name='playlistChecklist'))->'playlist' where name='playlist';
reset role;
create function private.test_abort_playlist_item() returns trigger language plpgsql set search_path='' as $$begin raise exception using errcode='P0001',message='INJECTED_PLAYLIST_FAILURE';end$$;
create trigger abort_playlist_item before insert on private.playlist_version_items for each row execute function private.test_abort_playlist_item();
set local role authenticated;
select throws_ok(format('select public.publish_creator_playlist(%L,%L,2,%L)',value->>'id','73000000-0000-4000-8000-000000000018',value->'review'->>'id'),'P0001','INJECTED_PLAYLIST_FAILURE','publication fails atomically after version insert') from playlist_authoring_state where name='playlist';
reset role;
select is((select count(*)::integer from private.playlist_versions where playlist_id=(select (value->>'id')::uuid from playlist_authoring_state where name='playlist')),0,'failed publication leaves no version');
select is((select count(*)::integer from private.playlist_commands where request_id='73000000-0000-4000-8000-000000000018'),0,'failed publication leaves no receipt');
drop trigger abort_playlist_item on private.playlist_version_items;
set local role authenticated;
insert into playlist_authoring_state select 'publish1',public.publish_creator_playlist((value->>'id')::uuid,'73000000-0000-4000-8000-000000000018',2,(value->'review'->>'id')::uuid) from playlist_authoring_state where name='playlist';
select is(value->'playlist'->'publication'->>'availability','available','retry after rollback publishes full available version') from playlist_authoring_state where name='publish1';
insert into playlist_authoring_state select 'publish2',public.publish_creator_playlist((value->'playlist'->>'id')::uuid,'73000000-0000-4000-8000-000000000019',3,(value->'playlist'->'review'->>'id')::uuid) from playlist_authoring_state where name='publish1';
select isnt((select value->>'publishedVersion' from playlist_authoring_state where name='publish1'),(select value->>'publishedVersion' from playlist_authoring_state where name='publish2'),'explicit publish receives fresh publication UUID even for same content');
select is(public.publish_creator_playlist((value->>'id')::uuid,'73000000-0000-4000-8000-000000000018',2,(value->'review'->>'id')::uuid)->>'publishedVersion',(select value->>'publishedVersion' from playlist_authoring_state where name='publish1'),'delayed retry identifies its original publication after republish') from playlist_authoring_state where name='playlist';
select public.save_creator_profile('73000000-0000-4000-8000-000000000020',1,'New Coach');
select is(public.get_library_playlist((value->'playlist'->>'id')::uuid)->'credit'->>'displayName','Coach','profile edits do not rewrite public publication credit') from playlist_authoring_state where name='publish2';
select is(public.get_creator_playlist((value->'playlist'->>'id')::uuid)->'review','null'::jsonb,'profile edit invalidates stale review') from playlist_authoring_state where name='publish2';
select throws_ok(format('select public.review_creator_playlist(%L,%L,4,1,%L::jsonb)',value->'playlist'->>'id','73000000-0000-4000-8000-000000000021',(select value from playlist_authoring_state where name='playlistChecklist')::text),'P0001','CREATOR_PROFILE_CONFLICT','review cannot approve credit changed after preview') from playlist_authoring_state where name='publish2';
reset role;
select * from finish();
rollback;
